package dev.odin.controls;
import android.content.*;import android.os.*;import android.provider.Settings;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;
/** Snapshots the global baseline before game overrides. Runtime snapshots never enter portable backups. */
final class GameProfileSession {
 static final String[] KINDS={"led","fan","cpu"};static final AtomicLong generation=new AtomicLong();static final Object BOOT_LOCK=new Object();
 static SharedPreferences store(Context c){synchronized(BOOT_LOCK){SharedPreferences p=c.getSharedPreferences("game-profile-session",0);int boot=PerformanceOwnership.boot(c);if(p.getInt("boot",-2)!=boot)p.edit().clear().putInt("boot",boot).commit();return p;}}
 static void globalChoice(Context c,String kind){generation.incrementAndGet();store(c).edit().remove("global_"+kind).remove("applied_"+kind).commit();}
 static boolean cpuOverride(Context c){return store(c).contains("global_cpu");}
 static JSONObject metadata(Context c,String... keys)throws Exception{JSONObject o=new JSONObject();Map<String,?> all=c.getSharedPreferences("profile",0).getAll();for(String k:keys)if(all.containsKey(k))o.put(k,all.get(k));return o;}
 static void restoreMetadata(Context c,JSONObject saved,String... keys)throws Exception{SharedPreferences.Editor edit=c.getSharedPreferences("profile",0).edit();for(String k:keys){if(!saved.has(k))edit.remove(k);else if(saved.get(k) instanceof Boolean)edit.putBoolean(k,saved.getBoolean(k));else edit.putString(k,saved.getString(k));}if(!edit.commit())throw new Exception("Could not restore global profile metadata");}
 static final String[] LED_META={"activeLED","lastLEDProfile","tileLEDSelection","tileLEDConfig","ledObserved","ledGroupObserved","ledGroupStateObserved","ledAnalogOn","ledSideOn"};
 static JSONObject capture(Context c,String kind)throws Exception{JSONObject out=new JSONObject();SharedPreferences p=c.getSharedPreferences("profile",0);
  if(kind.equals("cpu")){PerformancePanel.Status live=new PerformancePanel.Status(Root.run(c,"performance-status"));if(live.guard.equals("recovery"))throw new Exception("Resolve CPU safe recovery in Raven before applying a game override");boolean owned=PerformanceOwnership.active(c)&&p.contains("performanceActiveConfig")&&live.current.effectiveMatches(PerformancePanel.decode(new JSONObject(p.getString("performanceActiveConfig","{}"))));out.put("owned",owned);if(owned){out.put("name",p.getString("performanceActiveName","Global CPU profile"));out.put("config",new JSONObject(p.getString("performanceActiveConfig","{}")));}}
  else if(kind.equals("fan")){String name=ProfileActions.currentFanProfile(c);out.put("name",FanService.running?name:"");if(FanService.running&&!ProfileActions.names(c,true).contains(name))throw new Exception("Save the active global fan profile before adding a game fan override");JSONObject values=new JSONObject();for(String key:new String[]{"fan_mode","fan_speed","smart_fan_mode_switch"})values.put(key,nullable(DeviceState.get(c,key)));out.put("values",values);out.put("metadata",metadata(c,"activeFan","lastFanProfile","tileFanSelection"));}
  else{out.put("segments",SegmentSession.packed(c));out.put("segmentStockColors",c.getSharedPreferences("profile",0).getString("segmentStockColors",JSONObject.NULL.toString()));JSONObject values=new JSONObject();for(String key:DeviceState.LED_KEYS)values.put(key,nullable(DeviceState.get(c,key)));out.put("values",values);out.put("metadata",metadata(c,LED_META));}return out;
 }
 static Object nullable(String s){return s.equals("null")?JSONObject.NULL:s;}
 static void setting(Context c,String key,Object value)throws Exception{String v=value==JSONObject.NULL?null:(String)value;String cmd="settings --user 0 "+(v==null?"delete system "+key:"put system "+key+" "+Root.q(v))+" >/dev/null 2>&1 && echo OK";String answer=Root.call(cmd);if(!answer.startsWith("OK")||!DeviceState.get(c,key).equals(v==null?"null":v))throw new Exception("Could not restore global control setting");}
 static void waitClosing()throws Exception{long end=SystemClock.uptimeMillis()+10000;while(FanService.closingNow()&&SystemClock.uptimeMillis()<end)Thread.sleep(50);if(FanService.closingNow())throw new Exception("Fan control is still changing; retry");}
 static void stopFan(Context c)throws Exception{if(FanService.instance!=null){c.startForegroundService(new Intent(c,FanService.class).setAction("stock").putExtra("mode",4).putExtra("gameOverride",true));long end=SystemClock.uptimeMillis()+10000;while(FanService.instance!=null&&SystemClock.uptimeMillis()<end)Thread.sleep(50);if(FanService.instance!=null)throw new Exception("Cannot stop game fan session");}waitClosing();}
 static void fan(Context c,String name)throws Exception{waitClosing();int mode=name.equals("Quiet · stock")?1:name.equals("Smart · stock")?4:name.equals("Sport · stock")?5:new JSONObject(c.getSharedPreferences("profile",0).getString("fan:"+name,"{}")).optInt("stockMode",-1);boolean stock=mode>=0;
  if(stock&&DeviceState.get(c,"fan_mode").equals(""+mode)&&!FanService.running)return;
  long revision=FanService.appliedRevision.get();ProfileActions.applyScoped(c,true,name);long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){if(FanService.appliedRevision.get()>revision){if(stock){if(!FanService.running&&DeviceState.get(c,"fan_mode").equals(""+mode)){waitClosing();return;}}else if(FanService.running&&name.equals(ProfileActions.currentFanProfile(c)))return;}Thread.sleep(80);}throw new Exception("Fan profile was not confirmed: "+FanService.status);
 }
 static void apply(Context c,String kind,String name)throws Exception{if(kind.equals("cpu"))ProfileBridgeProvider.applyCpuScoped(c,name);else if(kind.equals("fan"))fan(c,name);else LedProfileService.applyAndWait(c,name);}
 static void restore(Context c,String kind,JSONObject snapshot,int odinCpu)throws Exception{
  if(kind.equals("cpu")){if(snapshot.optBoolean("owned"))ProfileBridgeProvider.applyCpuConfig(c,snapshot.getString("name"),PerformancePanel.decode(snapshot.getJSONObject("config")));else PerformanceOwnership.stock(c,odinCpu);}
  else if(kind.equals("fan")){String name=snapshot.optString("name");if(!name.isEmpty()&&c.getSharedPreferences("profile",0).getBoolean("fanControlEnabled",false))fan(c,name);else{if(FanService.instance!=null){c.startForegroundService(new Intent(c,FanService.class).setAction("stock").putExtra("mode",4).putExtra("gameOverride",true));long end=SystemClock.uptimeMillis()+10000;while(FanService.instance!=null&&SystemClock.uptimeMillis()<end)Thread.sleep(50);if(FanService.instance!=null)throw new Exception("Cannot stop game fan session");}JSONObject values=snapshot.getJSONObject("values");for(String key:new String[]{"fan_speed","smart_fan_mode_switch","fan_mode"})setting(c,key,values.get(key));restoreMetadata(c,snapshot.getJSONObject("metadata"),"activeFan","lastFanProfile","tileFanSelection");}}
  else{JSONObject values=snapshot.getJSONObject("values");for(String key:DeviceState.LED_KEYS)setting(c,key,values.get(key));if(!snapshot.optString("segments").isEmpty()){c.getSharedPreferences("profile",0).edit().putString("segmentStockColors",snapshot.optString("segmentStockColors","null")).commit();String mask=DeviceState.get(c,"joystick_light_enabled");Root.run(c,"light-segments "+snapshot.getString("segments")+" "+(mask.matches("[01],[01]")?mask:"0,0"));}else SegmentSession.forget(c);restoreMetadata(c,snapshot.getJSONObject("metadata"),LED_META);}
 }
 static synchronized Bundle sync(Context c,String game,JSONObject choices,String strict,int odinCpu)throws Exception{if(odinCpu<0||odinCpu>2)throw new Exception("Invalid Odin CPU mode");if(game==null||(!game.isEmpty()&&!game.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)*"))||game.length()>200)throw new Exception("Invalid game identity");if(choices.length()>3)throw new Exception("Invalid game choices");for(Iterator<String> i=choices.keys();i.hasNext();)if(!Arrays.asList(KINDS).contains(i.next()))throw new Exception("Unknown game profile kind");SharedPreferences state=store(c);if(!game.equals(state.getString("game","")))state.edit().putString("game",game).remove("suspended_fan").commit();JSONArray missing=new JSONArray();long epoch=generation.get();
  for(String kind:KINDS){String requested=choices.optString(kind,"");dev.raven.profileformat.PortableProfiles.name(choices.has(kind)?choices.get(kind):"",true);boolean exists=requested.isEmpty()||ProfileBridgeProvider.names(c,kind).contains(requested);if(!exists){if(kind.equals(strict))throw new Exception("The selected Raven profile is no longer available");missing.put(kind+": "+requested);}}
  for(String kind:KINDS){if(epoch!=generation.get())throw new Exception("Global profile changed; reopen the game picker");String name=choices.optString(kind,"");if(!name.isEmpty()&&!ProfileBridgeProvider.names(c,kind).contains(name))name="";String prior=state.getString("applied_"+kind,"");if(kind.equals("cpu")&&name.isEmpty()&&strict.equals("cpu")&&!state.contains("global_cpu")&&!PerformanceOwnership.active(c))PerformanceOwnership.stock(c,odinCpu);String signature=name;if(!name.isEmpty()){String key=ProfileDefinitions.prefix(kind)+name;String definition=c.getSharedPreferences("profile",0).getString(key,"");signature=name+"|"+definition;}if(kind.equals("fan")&&!name.isEmpty()&&signature.equals(state.getString("suspended_fan",""))&&!strict.equals("fan")){missing.put("fan: Odin cooling retained after temperature fallback");continue;}if(signature.equals(prior)&&!(name.isEmpty()&&state.contains("global_"+kind)))continue;
   if(name.isEmpty()){if(state.contains("global_"+kind)){restore(c,kind,new JSONObject(state.getString("global_"+kind,"{}")),odinCpu);state.edit().remove("global_"+kind).remove("applied_"+kind).commit();}}
   else{if(!c.getSharedPreferences("profile",0).getBoolean("setupCompleteV2",false))throw new Exception("Complete Guided Setup in Raven first");if(!state.contains("global_"+kind)&&!state.edit().putString("global_"+kind,capture(c,kind).toString()).commit())throw new Exception("Could not preserve global profile");try{apply(c,kind,name);if(epoch!=generation.get())throw new Exception("Global profile changed");if(!state.edit().putString("applied_"+kind,signature).commit())throw new Exception("Could not retain game profile session");}catch(Exception e){if(kind.equals("fan")&&((e.getMessage()==null?"":e.getMessage()).contains("temperature-fallback"))){stopFan(c);state.edit().remove("global_fan").remove("applied_fan").putString("suspended_fan",signature).commit();if(strict.equals("fan"))throw e;missing.put("fan: Odin cooling retained after temperature fallback");continue;}try{restore(c,kind,new JSONObject(state.getString("global_"+kind,"{}")),odinCpu);state.edit().remove("global_"+kind).remove("applied_"+kind).commit();}catch(Exception recovery){e.addSuppressed(recovery);}throw e;}}
  }Bundle result=new Bundle();result.putBoolean("ok",true);result.putString("missing",missing.toString());result.putBoolean("cpu_managed",PerformanceOwnership.active(c));return result;
 }
}
